package com.simibubi.create.test;

import com.simibubi.create.*;
import com.simibubi.create.content.decoration.copycat.*;
import com.simibubi.create.content.redstone.RoseQuartzLampBlock;
import com.simibubi.create.content.schematics.SchematicNbt;
import com.simibubi.create.content.schematics.requirement.ItemRequirement;
import java.util.*;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.ItemContainerContents;
import net.minecraft.world.item.context.*;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.*;
import net.minecraft.world.phys.*;

/** Actual native material, player, BlockItem, save, protection, loot and redstone cases. Runtime UNRUN. */
public final class CopycatGameTests {
    private static final BlockPos P=new BlockPos(2,3,2);
    private static NativeSurvivalTestPlayer player(GameTestHelper h,BlockPos pos){return NativeSurvivalTestPlayer.join(h,Vec3.atCenterOf(pos).add(0,2,3));}
    private static ItemStack named(Item item,int count){var stock=new ItemStack(item,count);stock.set(DataComponents.CUSTOM_NAME,Component.literal("Original native Copycat material"));return stock;}
    private static ItemStack cargo(){var stack=named(Items.BARREL,1);stack.set(DataComponents.CONTAINER,ItemContainerContents.fromItems(List.of(named(Items.EMERALD,7))));return stack;}
    private static CopycatBlockEntity fixture(GameTestHelper h,BlockPos pos,BlockState state){h.getLevel().setBlockAndUpdate(pos,state);return (CopycatBlockEntity)h.getLevel().getBlockEntity(pos);}
    private static InteractionResult use(ServerPlayer player,BlockPos pos,Direction face,double height){return player.gameMode.useItemOn(player,player.level(),player.getMainHandItem(),InteractionHand.MAIN_HAND,new BlockHitResult(new Vec3(pos.getX()+.5,pos.getY()+height,pos.getZ()+.5),face,pos,false));}
    private static InteractionResult apply(ServerPlayer player,BlockPos pos,Direction face){return use(player,pos,face,.75);}
    private static InteractionResult wrench(ServerPlayer player,BlockPos pos,boolean sneak){player.getInventory().setItem(0,new ItemStack(AllItems.WRENCH));player.setShiftKeyDown(sneak);try{return AllItems.WRENCH.useOn(new UseOnContext(player,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(pos),Direction.UP,pos,false)));}finally{player.setShiftKeyDown(false);}}
    private static int loose(GameTestHelper h,BlockPos pos,Item item){return h.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(pos).inflate(1.5)).stream().filter(entity->entity.getItem().is(item)).mapToInt(entity->entity.getItem().getCount()).sum();}
    private static boolean containsIdentity(Throwable thrown,Throwable expected){var seen=Collections.newSetFromMap(new IdentityHashMap<Throwable,Boolean>());while(thrown!=null&&seen.add(thrown)){if(thrown==expected)return true;thrown=thrown.getCause();}return false;}

    @GameTest public void sourceHelperBlockIdsNeverInventBaseOrBarsItems(GameTestHelper h){h.assertTrue(BuiltInRegistries.BLOCK.getKey(AllBlocks.COPYCAT_BASE).equals(Create.asResource("copycat_base"))&&BuiltInRegistries.BLOCK.getKey(AllBlocks.COPYCAT_BARS).equals(Create.asResource("copycat_bars")),"Both real source helper block IDs are registered");h.assertTrue(AllBlocks.COPYCAT_BASE.asItem()==Items.AIR&&AllBlocks.COPYCAT_BARS.asItem()==Items.AIR&&!BuiltInRegistries.ITEM.containsKey(Create.asResource("copycat_base"))&&!BuiltInRegistries.ITEM.containsKey(Create.asResource("copycat_bars")),"Source helpers deliberately have no item registration");h.assertTrue(AllBlocks.COPYCAT_PANEL.asItem()!=Items.AIR&&AllBlocks.COPYCAT_STEP.asItem()!=Items.AIR&&AllBlocks.ROSE_QUARTZ_LAMP.asItem()!=Items.AIR,"Only actual source user-facing items are registered");h.succeed();}
    @GameTest public void sourceThreePixelPanelAndHalfByHalfStepHaveLiteralNativeShapes(GameTestHelper h){var pos=h.absolutePos(P);for(var side:Direction.values()){var state=AllBlocks.COPYCAT_PANEL.defaultBlockState().setValue(CopycatPanelBlock.FACING,side);var shape=state.getShape(h.getLevel(),pos).bounds();var expected=switch(side){case UP->new AABB(0,0,0,1,3/16d,1);case DOWN->new AABB(0,13/16d,0,1,1,1);case NORTH->new AABB(0,0,13/16d,1,1,1);case SOUTH->new AABB(0,0,0,1,1,3/16d);case EAST->new AABB(0,0,0,3/16d,1,1);case WEST->new AABB(13/16d,0,0,1,1,1);};h.assertValueEqual(shape,expected,"Independent source panel extent "+side);}var step=AllBlocks.COPYCAT_STEP.defaultBlockState();h.assertValueEqual(step.getShape(h.getLevel(),pos).bounds(),new AABB(0,0,.5,1,.5,1),"Pinned SOUTH/BOTTOM native half-by-half step");h.assertValueEqual(step.setValue(CopycatStepBlock.HALF,Half.TOP).setValue(CopycatStepBlock.FACING,Direction.EAST).getShape(h.getLevel(),pos).bounds(),new AABB(.5,.5,0,1,1,1),"Independent EAST/TOP source quarter volume");h.succeed();}
    @GameTest public void sourceMaterialAllowDenyAndPanelSpecialCasesUseRealTagsAndShapes(GameTestHelper h){var pos=h.absolutePos(P);var panel=AllBlocks.COPYCAT_PANEL;var step=AllBlocks.COPYCAT_STEP;h.assertTrue(step.getAcceptedBlockState(h.getLevel(),pos,new ItemStack(Items.STONE),Direction.UP)!=null&&step.getAcceptedBlockState(h.getLevel(),pos,new ItemStack(Items.BARREL),Direction.UP)!=null,"Full cube and actual source allow-tag barrel are accepted");for(var item:List.of(Items.OAK_STAIRS,Items.DIRT_PATH,Items.CAULDRON,AllBlocks.COPYCAT_PANEL.asItem()))h.assertTrue(step.getAcceptedBlockState(h.getLevel(),pos,new ItemStack(item),Direction.UP)==null,"Actual source deny/noncube/recursive material refuses "+item);for(var item:List.of(Items.IRON_BARS,Items.OAK_TRAPDOOR))h.assertTrue(panel.getAcceptedBlockState(h.getLevel(),pos,new ItemStack(item),Direction.EAST)!=null&&step.getAcceptedBlockState(h.getLevel(),pos,new ItemStack(item),Direction.EAST)==null,"Bars/trapdoor source exception belongs only to Panel");h.succeed();}
    @GameTest public void actualNamedMaterialPaysOneOwnedReceiptAndRepeatedStoneCannotDebit(GameTestHelper h){var pos=h.absolutePos(P);var copycat=fixture(h,pos,AllBlocks.COPYCAT_PANEL.defaultBlockState());try(var joined=player(h,pos)){var player=joined.player();var original=named(Items.STONE,3);player.getInventory().setItem(0,original);h.assertTrue(apply(player,pos,Direction.UP).consumesAction(),"Native original game-mode item interaction accepts material");h.assertTrue(original.getCount()==2&&copycat.getMaterial().is(Blocks.STONE)&&ItemStack.matches(copycat.getConsumedItem(),named(Items.STONE,1)),"Exactly one original named item becomes the actual BE receipt");h.getLevel().setBlockAndUpdate(pos.above(),Blocks.BEDROCK.defaultBlockState());apply(player,pos,Direction.UP);h.assertTrue(h.getLevel().getBlockState(pos.above()).is(Blocks.BEDROCK),"Source non-cycling PASS cannot place an ordinary material into the occupied fallback cell");h.assertTrue(original.getCount()==2&&ItemStack.matches(copycat.getConsumedItem(),named(Items.STONE,1)),"A material without cycle properties cannot debit a second item");var observed=copycat.getConsumedItem();observed.setCount(0);h.assertValueEqual(copycat.getConsumedItem().getCount(),1,"Detached public observation cannot mutate the actual material owner");}h.succeed();}
    @GameTest public void actualNativeBlockItemPlacementConsumesOriginalWrapperAndOffhandMaterial(GameTestHelper h){var pos=h.absolutePos(P);h.getLevel().setBlockAndUpdate(pos,Blocks.AIR.defaultBlockState());try(var joined=player(h,pos)){var player=joined.player();var wrappers=new ItemStack(AllBlocks.COPYCAT_PANEL,2);var materials=named(Items.STONE,2);player.getInventory().setItem(0,wrappers);player.setItemInHand(InteractionHand.OFF_HAND,materials);var context=new BlockPlaceContext(player,InteractionHand.MAIN_HAND,wrappers,new BlockHitResult(Vec3.atCenterOf(pos),Direction.UP,pos,false));h.assertTrue(((BlockItem)wrappers.getItem()).place(context).consumesAction(),"Actual native original wrapper BlockItem.place accepted");var copycat=(CopycatBlockEntity)h.getLevel().getBlockEntity(pos);h.assertTrue(wrappers.getCount()==1&&materials.getCount()==1&&copycat.getMaterial().is(Blocks.STONE)&&ItemStack.matches(copycat.getConsumedItem(),named(Items.STONE,1)),"Native setPlacedBy transfers one real offhand receipt and native tail consumes one actual wrapper");}h.succeed();}
    @GameTest public void actualAllowedBarrelCargoSurvivesNativeItemCodecWithoutSpawningBarrelOwner(GameTestHelper h){var pos=h.absolutePos(P);var copycat=fixture(h,pos,AllBlocks.COPYCAT_PANEL.defaultBlockState());try(var joined=player(h,pos)){var player=joined.player();var original=cargo();player.getInventory().setItem(0,original);h.assertTrue(apply(player,pos,Direction.EAST).consumesAction()&&original.isEmpty(),"One actual allowed cargo-bearing barrel is consumed");h.assertTrue(h.getLevel().getBlockEntity(pos)==copycat&&copycat.getMaterial().is(Blocks.BARREL)&&ItemStack.matches(copycat.getConsumedItem(),cargo()),"Material appearance creates no BarrelBE and preserves the sole original item/cargo components");var restored=BlockEntity.loadStatic(pos,copycat.getBlockState(),copycat.saveWithFullMetadata(h.getLevel().registryAccess()),h.getLevel().registryAccess());h.assertTrue(restored instanceof CopycatBlockEntity decoded&&decoded.getLevel()==null&&ItemStack.matches(decoded.getConsumedItem(),cargo())&&decoded.getMaterial()==copycat.getMaterial(),"Actual native BE/registered ItemStack codecs retain exact material and seven named emeralds in a detached decode, not a second world owner");h.assertTrue(wrench(player,pos,false).consumesAction()&&player.getInventory().countItem(Items.BARREL)==1,"Native wrench returns one original cargo owner");var returned=java.util.stream.IntStream.range(0,player.getInventory().getContainerSize()).mapToObj(player.getInventory()::getItem).filter(stack->stack.is(Items.BARREL)).findFirst().orElseThrow();h.assertTrue(ItemStack.matches(returned,cargo())&&!copycat.ownsConsumedItem(),"Exactly one original complete barrel leaves custody, never cloned world cargo");}h.succeed();}
    @GameTest public void actualRequirementsContainWrapperAndStrictOriginalComponentMaterial(GameTestHelper h){var pos=h.absolutePos(P);var copycat=fixture(h,pos,AllBlocks.COPYCAT_PANEL.defaultBlockState());try(var joined=player(h,pos)){var player=joined.player();player.getInventory().setItem(0,named(Items.STONE,1));apply(player,pos,Direction.UP);var requirement=ItemRequirement.of(copycat.getBlockState(),copycat);h.assertValueEqual(requirement.getRequiredItems().size(),2,"Native source requirement is one wrapper plus one real material");var material=requirement.getRequiredItems().stream().filter(row->row.stack.is(Items.STONE)).findFirst().orElseThrow();h.assertTrue(material.stack.getCount()==1&&material.matches(named(Items.STONE,1))&&!material.matches(new ItemStack(Items.STONE)),"Actual material requirement retains original named component and exact single count");}h.succeed();}
    @GameTest public void actualMaterialCycleAndAdjacentAlignmentDoNotCreateAnotherReceipt(GameTestHelper h){var pos=h.absolutePos(P);var first=fixture(h,pos,AllBlocks.COPYCAT_PANEL.defaultBlockState());var second=fixture(h,pos.east(),AllBlocks.COPYCAT_PANEL.defaultBlockState());try(var joined=player(h,pos)){var player=joined.player();var stock=named(Items.OAK_LOG,3);player.getInventory().setItem(0,stock);apply(player,pos,Direction.EAST);h.assertTrue(first.getMaterial().getValue(BlockStateProperties.AXIS)==Direction.Axis.X,"Actual clicked face selects source log axis");apply(player,pos.east(),Direction.NORTH);h.assertTrue(second.getMaterial().getValue(BlockStateProperties.AXIS)==Direction.Axis.X&&stock.getCount()==1,"Same oriented adjacent wrapper aligns material to real neighbor and pays its own original item");apply(player,pos,Direction.UP);h.assertTrue(first.getMaterial().getValue(BlockStateProperties.AXIS)==Direction.Axis.Y&&stock.getCount()==1&&first.getConsumedItem().getCount()==1&&second.getConsumedItem().getCount()==1,"Source cycle changes actual material axis without charging or replacing either receipt");}h.succeed();}
    @GameTest public void actualWallTrapdoorPreparationAndOpenHalfCycleRetainOneOriginalItem(GameTestHelper h){var pos=h.absolutePos(P);var copycat=fixture(h,pos,AllBlocks.COPYCAT_PANEL.defaultBlockState().setValue(CopycatPanelBlock.FACING,Direction.EAST));try(var joined=player(h,pos)){var player=joined.player();var stock=new ItemStack(Items.OAK_TRAPDOOR,2);player.getInventory().setItem(0,stock);apply(player,pos,Direction.EAST);var state=copycat.getMaterial();h.assertTrue(state.getValue(TrapDoorBlock.OPEN)&&state.getValue(TrapDoorBlock.HALF)==Half.TOP&&state.getValue(TrapDoorBlock.FACING)==Direction.EAST&&stock.getCount()==1,"Actual source wall preparation uses near-top hit and panel facing");apply(player,pos,Direction.NORTH);h.assertTrue(copycat.getMaterial().getValue(TrapDoorBlock.HALF)==Half.BOTTOM&&copycat.getMaterial().getValue(TrapDoorBlock.FACING)==Direction.EAST&&stock.getCount()==1,"Actual open trapdoor cycles half before facing and never pays twice");}h.succeed();}
    @GameTest public void actualNativeBreakDropsOneWrapperAndOneOriginalNamedMaterial(GameTestHelper h){var pos=h.absolutePos(P);var copycat=fixture(h,pos,AllBlocks.COPYCAT_PANEL.defaultBlockState());try(var joined=player(h,pos)){var player=joined.player();player.getInventory().setItem(0,named(Items.STONE,1));apply(player,pos,Direction.UP);player.getInventory().setItem(0,new ItemStack(Items.DIAMOND_PICKAXE));h.assertTrue(player.gameMode.destroyBlock(pos)&&h.getLevel().getBlockState(pos).isAir(),"Actual native survival game-mode removal succeeds");h.assertTrue(loose(h,pos,AllBlocks.COPYCAT_PANEL.asItem())==1&&loose(h,pos,Items.STONE)==1&&!copycat.ownsConsumedItem(),"Native preRemoveSideEffects and actual loot each transfer only their original owner once");var material=h.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(pos).inflate(1.5)).stream().map(ItemEntity::getItem).filter(stack->stack.is(Items.STONE)).findFirst().orElseThrow();h.assertTrue(ItemStack.matches(material,named(Items.STONE,1)),"Native material drop retains original named components");}h.succeed();}
    @GameTest public void actualWrenchResetRefundsReceiptAndRetainsExistingWrapper(GameTestHelper h){var pos=h.absolutePos(P);var copycat=fixture(h,pos,AllBlocks.COPYCAT_PANEL.defaultBlockState());try(var joined=player(h,pos)){var player=joined.player();player.getInventory().setItem(0,named(Items.STONE,1));apply(player,pos,Direction.UP);h.assertTrue(wrench(player,pos,false).consumesAction()&&h.getLevel().getBlockEntity(pos)==copycat&&copycat.getMaterial().is(AllBlocks.COPYCAT_BASE)&&!copycat.ownsConsumedItem()&&player.getInventory().countItem(Items.STONE)==1,"Actual normal wrench retains wrapper and returns sole original material owner");h.assertFalse(wrench(player,pos,false).consumesAction(),"Untextured wrapper cannot refund again");h.assertValueEqual(player.getInventory().countItem(Items.STONE),1,"No duplicate second refund");}h.succeed();}
    @GameTest public void actualSneakWrenchReturnsBothOriginalOwnersWithoutWorldDrops(GameTestHelper h){var pos=h.absolutePos(P);var copycat=fixture(h,pos,AllBlocks.COPYCAT_STEP.defaultBlockState());try(var joined=player(h,pos)){var player=joined.player();player.getInventory().setItem(0,named(Items.STONE,1));apply(player,pos,Direction.UP);h.assertTrue(wrench(player,pos,true).consumesAction()&&h.getLevel().getBlockState(pos).isAir()&&player.getInventory().countItem(Items.STONE)==1&&player.getInventory().countItem(AllBlocks.COPYCAT_STEP.asItem())==1&&!copycat.ownsConsumedItem(),"Native sneak wrench returns one real material plus one actual source wrapper loot");h.assertTrue(loose(h,pos,Items.STONE)==0&&loose(h,pos,AllBlocks.COPYCAT_STEP.asItem())==0,"Owner transfer cannot also publish duplicate world drops");}h.succeed();}
    @GameTest public void actualBreakProtectionPrecedesSneakWrenchMaterialRefund(GameTestHelper h){var pos=h.absolutePos(P);var copycat=fixture(h,pos,AllBlocks.COPYCAT_PANEL.defaultBlockState());try(var joined=player(h,pos)){var player=joined.player();player.getInventory().setItem(0,cargo());apply(player,pos,Direction.UP);CopycatTestFixtures.denyBreak(h.getLevel(),pos);try{h.assertFalse(wrench(player,pos,true).consumesAction(),"Real Fabric BEFORE denies native wrench removal");h.assertTrue(h.getLevel().getBlockEntity(pos)==copycat&&ItemStack.matches(copycat.getConsumedItem(),cargo())&&player.getInventory().countItem(Items.BARREL)==0,"Denied target retains exact original receipt/cargo, no early refund or stale-owner overwrite");}finally{CopycatTestFixtures.clear();}}h.succeed();}
    @GameTest(maxTicks=100) public void nativeGlowstoneMaterialUpdatesActualVanillaLightEngine(GameTestHelper h){var pos=h.absolutePos(P);var copycat=fixture(h,pos,AllBlocks.COPYCAT_PANEL.defaultBlockState());try(var joined=player(h,pos)){var player=joined.player();player.getInventory().setItem(0,new ItemStack(Items.GLOWSTONE,2));apply(player,pos,Direction.UP);h.assertTrue(copycat.getMaterial().is(Blocks.GLOWSTONE)&&copycat.getBlockState().getValue(CopycatBlock.LIGHT)==15&&player.getMainHandItem().getCount()==1,"Actual paid material derives real vanilla light-emission state");}h.succeedWhen(()->{h.assertTrue(h.getLevel().getBlockEntity(pos)==copycat&&copycat.getMaterial().is(Blocks.GLOWSTONE)&&copycat.getBlockState().getValue(CopycatBlock.LIGHT)==15&&copycat.getConsumedItem().is(Items.GLOWSTONE)&&copycat.getConsumedItem().getCount()==1,"The real original paid glowstone remains owned by the same native Copycat while asynchronous light propagation completes");h.assertTrue(h.getLevel().getBrightness(LightLayer.BLOCK,pos.above())>=14,"Actual native block light propagates to a neighboring cell, independent of shader-only emission: actual="+h.getLevel().getBrightness(LightLayer.BLOCK,pos.above()));});}
    @GameTest public void sourceRoseQuartzMaterialCyclesPoweringAndNativeLightWithoutAdditionalCost(GameTestHelper h){var pos=h.absolutePos(P);var copycat=fixture(h,pos,AllBlocks.COPYCAT_PANEL.defaultBlockState());try(var joined=player(h,pos)){var player=joined.player();var stock=new ItemStack(AllBlocks.ROSE_QUARTZ_LAMP,2);player.getInventory().setItem(0,stock);apply(player,pos,Direction.UP);apply(player,pos,Direction.UP);h.assertTrue(copycat.getMaterial().getValue(RoseQuartzLampBlock.POWERING)&&copycat.getBlockState().getValue(CopycatBlock.LIGHT)==15&&stock.getCount()==1,"Source POWERING cycle is used when material has no LIT property");apply(player,pos,Direction.UP);h.assertTrue(!copycat.getMaterial().getValue(RoseQuartzLampBlock.POWERING)&&copycat.getBlockState().getValue(CopycatBlock.LIGHT)==0&&stock.getCount()==1,"Second source cycle turns actual material light off without consuming another lamp");}h.succeed();}
    @GameTest public void actualNativeUpdateErrorKeepsPaidReceiptAndOriginalCauseUntilRefund(GameTestHelper h){var pos=h.absolutePos(P);var copycat=fixture(h,pos,AllBlocks.COPYCAT_PANEL.defaultBlockState());h.getLevel().setBlockAndUpdate(pos.east(),CopycatTestFixtures.UPDATE_ERROR.defaultBlockState());try(var joined=player(h,pos)){var player=joined.player();var stock=named(Items.GLOWSTONE,2);player.getInventory().setItem(0,stock);var refusal=new CopycatTestFixtures.NativeRefusal("Real native light-state neighbor update");CopycatTestFixtures.arm(h.getLevel(),pos.east(),refusal);try{boolean thrown=false;try{apply(player,pos,Direction.UP);}catch(Throwable failure){thrown=true;h.assertTrue(containsIdentity(failure,refusal),"Actual native callback wrapping retains exact original Error cause");}h.assertTrue(thrown&&h.getLevel().getBlockEntity(pos)==copycat&&copycat.getMaterial().is(Blocks.GLOWSTONE)&&ItemStack.matches(copycat.getConsumedItem(),named(Items.GLOWSTONE,1))&&stock.getCount()==1,"Payment and canonical material receipt exist before real native publication callbacks, without free material or refund duplication");player.getInventory().setItem(3,player.getInventory().removeItemNoUpdate(0));wrench(player,pos,false);h.assertValueEqual(player.getInventory().countItem(Items.GLOWSTONE),2,"Actual later wrench returns accepted original payment once after Error cleanup");}finally{CopycatTestFixtures.clear();}}h.succeed();}
    @GameTest public void actualSafeSchematicDataStripsStockComponentsWithoutChangingLiveCargoOwner(GameTestHelper h){var pos=h.absolutePos(P);var copycat=fixture(h,pos,AllBlocks.COPYCAT_PANEL.defaultBlockState());try(var joined=player(h,pos)){var player=joined.player();player.getInventory().setItem(0,cargo());apply(player,pos,Direction.UP);var safe=SchematicNbt.prepare(h.getLevel(),copycat.getBlockState(),copycat);var ops=h.getLevel().registryAccess().createSerializationContext(net.minecraft.nbt.NbtOps.INSTANCE);var item=ItemStack.OPTIONAL_CODEC.parse(ops,safe.getCompoundOrEmpty("Item")).getOrThrow();h.assertTrue(item.is(Items.BARREL)&&item.getCount()==1&&item.getComponentsPatch().isEmpty()&&ItemStack.matches(item,new ItemStack(Items.BARREL))&&!item.getOrDefault(DataComponents.CONTAINER,ItemContainerContents.EMPTY).nonEmptyItems().iterator().hasNext()&&ItemStack.matches(copycat.getConsumedItem(),cargo()),"Source writeSafe makes only a plain paid blueprint requirement; actual live named seven-emerald receipt remains intact");}h.succeed();}
    @GameTest public void actualPanelPlacementAssistanceUsesRealNativeFiniteBlockItem(GameTestHelper h){var pos=h.absolutePos(P);fixture(h,pos,AllBlocks.COPYCAT_PANEL.defaultBlockState());h.getLevel().setBlockAndUpdate(pos.east(),Blocks.AIR.defaultBlockState());try(var joined=player(h,pos)){var player=joined.player();var stock=new ItemStack(AllBlocks.COPYCAT_PANEL,2);player.getInventory().setItem(0,stock);var hit=new BlockHitResult(Vec3.atLowerCornerOf(pos).add(.99,.1875,.5),Direction.UP,pos,false);h.assertTrue(player.gameMode.useItemOn(player,h.getLevel(),stock,InteractionHand.MAIN_HAND,hit).consumesAction(),"Actual native helper interaction selects nearest allowed face-plane neighbor");var installed=h.getLevel().getBlockState(pos.east());h.assertTrue(installed.is(AllBlocks.COPYCAT_PANEL)&&installed.getValue(CopycatPanelBlock.FACING)==Direction.UP&&stock.getCount()==1&&h.getLevel().getBlockEntity(pos.east()) instanceof CopycatBlockEntity created&&!created.ownsConsumedItem(),"One actual wrapper becomes one real native adjacent Copycat, with no invented paid material");}h.succeed();}
    @GameTest public void realTargetUseProtectionPreventsHelperNativePlacementAndDebit(GameTestHelper h){var pos=h.absolutePos(P);fixture(h,pos,AllBlocks.COPYCAT_PANEL.defaultBlockState());h.getLevel().setBlockAndUpdate(pos.east(),Blocks.AIR.defaultBlockState());try(var joined=player(h,pos)){var player=joined.player();var stock=new ItemStack(AllBlocks.COPYCAT_PANEL,2);player.getInventory().setItem(0,stock);CopycatTestFixtures.denyUse(h.getLevel(),pos.east());try{var hit=new BlockHitResult(Vec3.atLowerCornerOf(pos).add(.99,.1875,.5),Direction.UP,pos,false);player.gameMode.useItemOn(player,h.getLevel(),stock,InteractionHand.MAIN_HAND,hit);h.assertTrue(h.getLevel().getBlockState(pos.east()).isAir()&&stock.getCount()==2,"Real new-target UseBlock refusal preserves both original finite wrappers");}finally{CopycatTestFixtures.clear();}}h.succeed();}
    @GameTest public void sourceLampPowerEdgeFocusesActualClusterAndComparatorDistance(GameTestHelper h){var pos=h.absolutePos(P);for(int index=0;index<3;index++)h.getLevel().setBlockAndUpdate(pos.east(index),AllBlocks.ROSE_QUARTZ_LAMP.defaultBlockState());h.getLevel().setBlockAndUpdate(pos.north(),Blocks.REDSTONE_BLOCK.defaultBlockState());h.runAfterDelay(3,()->{h.assertTrue(h.getLevel().getBlockState(pos).getValue(RoseQuartzLampBlock.POWERING)&&!h.getLevel().getBlockState(pos).getValue(RoseQuartzLampBlock.ACTIVATE),"Original actual native rising edge retains winner after source one-tick activation");h.getLevel().setBlockAndUpdate(pos.east(2).north(),Blocks.REDSTONE_BLOCK.defaultBlockState());h.runAfterDelay(3,()->{h.assertTrue(!h.getLevel().getBlockState(pos).getValue(RoseQuartzLampBlock.POWERING)&&h.getLevel().getBlockState(pos.east(2)).getValue(RoseQuartzLampBlock.POWERING),"Later actual native edge transfers cluster focus while first input remains powered");h.getLevel().setBlockAndUpdate(pos.west(),Blocks.COMPARATOR.defaultBlockState());h.assertValueEqual(h.getLevel().getBlockState(pos).getSignal(h.getLevel(),pos,Direction.EAST),13,"Actual comparator neighbor reads source15-minus-distance along the native lamp column");h.succeed();});});}
}
